// SIG experimental: correspondencia IBGE automatica nao substitui auditoria das fichas.
const $=id=>document.getElementById(id);
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,' ').trim().toUpperCase();
const safeUrl=value=>{try{const u=new URL(String(value));return u.protocol==='https:'&&/(^|\.)ppi\.gov\.br$/.test(u.hostname)?u.href:null}catch{return null}};
const state={records:[],map:null,layer:null,selection:0};
const setStatus=(msg,error=false)=>{$('status').textContent=msg;$('status').className=error?'error':'good'};
const field=(p,key)=>String(p[key]??'').trim()||'Não informado';
function audit(projects,municipalities){
 const index=new Map();for(const m of municipalities){const uf=m.microrregiao?.mesorregiao?.UF?.sigla??m['regiao-imediata']?.['regiao-intermediaria']?.UF?.sigla;if(!uf)continue;const key=uf+'|'+norm(m.nome);index.set(key,[...(index.get(key)||[]),m]);}
 const ids=new Set();return projects.map(p=>{
  const raw=String(p.municipio??'').trim(),uf=String(p.uf??'').trim().toUpperCase(),match=raw.match(/^(.+?)\s*\(([A-Z]{2})\)\s*$/),name=(match?match[1]:raw).trim(),issues=[];
  const id=String(p.numero??'').trim();if(!id||ids.has(id))issues.push('Número ausente ou duplicado');else ids.add(id);
  if(match&&match[2]!==uf)issues.push('UF divergente');if(!name||!uf)issues.push('Município ou UF ausente');
  if(/[,;/]|\s+e\s+/i.test(name))issues.push('Possível abrangência de múltiplos municípios');
  if(/cons[oó]rcio/i.test([p.projeto,p.municipio,p.categoria].join(' ')))issues.push('Consórcio: sede não comprovada na ficha');
  if(/\b(estadual|regional|intermunicipal|metropolitano|multimunicipal|microrregional)\b/i.test([p.projeto,p.municipio].join(' ')))issues.push('Abrangência territorial exige revisão');
  const matches=index.get(uf+'|'+norm(name))||[];if(matches.length!==1)issues.push(matches.length?'Correspondência IBGE ambígua':'Município não localizado no IBGE');
  return {p,name,uf,ibge:matches.length===1?matches[0]:null,issues};
 });
}
const filters=['uf','categoria','modalidade','etapa','situacao'];
function populateFilters(){for(const id of filters){const select=$(id),values=[...new Set(state.records.map(r=>id==='uf'?(r.uf||'Não informado'):field(r.p,id==='situacao'?'status':id)))].sort((a,b)=>a.localeCompare(b,'pt-BR'));for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option);}}}
function clearMap(){++state.selection;if(state.layer&&state.map){state.map.removeLayer(state.layer);state.layer=null;}$('detail').textContent='Selecione um projeto elegível para consultar sua malha municipal. O mapa não indica o local da obra.';}
function render(){const q=norm($('search').value),review=$('review').value;const selected=state.records.filter(r=>filters.every(id=>{const value=$(id).value;return !value||value===(id==='uf'?(r.uf||'Não informado'):field(r.p,id==='situacao'?'status':id));})&&(!q||norm([r.p.numero,r.p.projeto,r.name,r.uf,r.p.categoria,r.p.modalidade].join(' ')).includes(q))&&(review==='all'||(review==='pending'?r.issues.length>0:r.issues.length===0)));const list=$('projects');list.replaceChildren();$('filtered').textContent=`${selected.length} de ${state.records.length} projetos no recorte · ${selected.filter(r=>!r.issues.length).length} candidatos · ${selected.filter(r=>r.issues.length).length} pendências. Os filtros não comprovam a localização das obras.`;for(const r of selected){const li=document.createElement('li'),name=document.createElement('strong');name.textContent=`${r.p.numero??'—'} · ${r.p.projeto??'Projeto sem título'}`;li.append(name);const desc=document.createElement('div');desc.className='small';desc.textContent=`${r.name||'Município não informado'} / ${r.uf||'UF não informada'} · ${field(r.p,'categoria')} · ${field(r.p,'modalidade')} · ${field(r.p,'etapa')} · ${field(r.p,'status')} · ${r.issues.length?r.issues.join('; '):'Código IBGE '+r.ibge.id+' (geometria não conferida)'}`;li.append(desc);if(!r.issues.length){const btn=document.createElement('button');btn.textContent='Consultar geometria oficial no mapa';btn.addEventListener('click',()=>draw(r));li.append(btn);}const url=safeUrl(r.p.url);if(url){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Ficha/página oficial PPI';li.append(a);}list.append(li);}if(!selected.length){const li=document.createElement('li');li.textContent='Nenhum registro neste filtro.';list.append(li);}}
function geometryValid(g){return g&&((g.type==='Feature'&&g.geometry&&['Polygon','MultiPolygon'].includes(g.geometry.type))||(['Polygon','MultiPolygon'].includes(g.type))||(g.type==='FeatureCollection'&&Array.isArray(g.features)&&g.features.length>0&&g.features.every(f=>f.geometry&&['Polygon','MultiPolygon'].includes(f.geometry.type))));}
async function draw(r){if(r.issues.length||!r.ibge)return;const ticket=++state.selection;const detail=$('detail');detail.textContent=`Consultando malha IBGE do município ${r.name} (${r.uf}), código ${r.ibge.id}…`;const url=`https://servicodados.ibge.gov.br/api/v3/malhas/municipios/${encodeURIComponent(r.ibge.id)}?formato=application%2Fvnd.geo%2Bjson`;
 try{const response=await fetch(url,{headers:{Accept:'application/vnd.geo+json, application/geo+json, application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);const geo=await response.json();if(ticket!==state.selection)return;if(!geometryValid(geo))throw new Error('A API não retornou GeoJSON poligonal válido');const layer=L.geoJSON(geo,{style:{color:'#135a82',weight:2,fillColor:'#2d87ae',fillOpacity:.35}});if(!layer.getBounds().isValid())throw new Error('Geometria sem limites válidos');if(state.layer)state.map.removeLayer(state.layer);state.layer=layer.addTo(state.map);state.map.fitBounds(layer.getBounds(),{padding:[20,20]});detail.textContent=`Polígono carregado da API IBGE: ${r.name} (${r.uf}), código ${r.ibge.id}. É o limite municipal, NÃO o local da obra. Sede de consórcios não foi inferida.`;
 }catch(error){if(ticket!==state.selection)return;detail.textContent=`Geometria não validada para ${r.name}: ${error.message}. Verifique acesso à API, formato GeoJSON e disponibilidade do serviço. Nenhum ponto foi estimado.`;}}
async function init(){if(!window.L){setStatus('Biblioteca do mapa indisponível. Verifique a conexão.',true);return;}state.map=L.map('map').setView([-15.7,-52.8],4);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors; limites municipais: IBGE'}).addTo(state.map);
 try{const [base,ibge]=await Promise.all([fetch('./data.json'),fetch('https://servicodados.ibge.gov.br/api/v1/localidades/municipios')]);if(!base.ok||!ibge.ok)throw new Error(`Base HTTP ${base.status}; IBGE HTTP ${ibge.status}`);const [projects,municipalities]=await Promise.all([base.json(),ibge.json()]);if(!Array.isArray(projects)||!Array.isArray(municipalities)||municipalities.length<5000)throw new Error('Formato de dados inesperado ou cadastro IBGE incompleto');state.records=audit(projects,municipalities);const ready=state.records.filter(r=>!r.issues.length).length;const pending=state.records.length-ready;populateFilters();$('summary').textContent=`Base: ${state.records.length} registros · ${ready} candidatos com código municipal único (ainda sem conferência das fichas e da geometria) · ${pending} pendências automáticas. Geometrias: carregadas individualmente sob demanda.`;setStatus('Auditoria preliminar carregada; nenhuma localização de obra foi inferida.');render();
 }catch(error){setStatus('Falha ao carregar base ou cadastro IBGE: '+error.message,true);$('detail').textContent='Mapa sem dados de projetos; não há geometrias verificadas.';}}
for(const id of [...filters,'search','review'])$(id).addEventListener(id==='search'?'input':'change',()=>{clearMap();render();});$('clear').addEventListener('click',()=>{for(const id of [...filters,'review'])$(id).value=id==='review'?'ready':'';$('search').value='';clearMap();render();});init();